export async function createFeatureHistory(args: HistoryArgs & { input: RectangularFeatureInput }) { await authorize(args); const values = { width: toMm(args.input.width, args.input.unit), height: toMm(args.input.height, args.input.unit), extrudeDistance: toMm(args.input.extrudeDistance, args.input.unit) }; const revision = await build({ ...args, title: args.input.title, values, decision: "Created a real rectangular sketch-to-extrude feature chain." }); if (revision.status === "FAILED") { await persistFailure(args, revision); return revision; } histories.set(args.projectId, [...(histories.get(args.projectId) ?? []), revision]); await persistRevision(args, revision); return revision; }
