export async function listFeatureHistory(args: HistoryArgs) { await authorize(args); const snapshot = await projectMemorySnapshot(args); const durable = snapshot.records.filter((record) => record.kind === "FEATURE_REVISION").flatMap((record) => { try { return [(JSON.parse(record.content) as { revision: FeatureHistoryRevision }).revision]; } catch { return []; } }); const cached = histories.get(args.projectId) ?? []; const combined = [...durable, ...cached].filter((item, index, all) => all.findIndex((candidate) => candidate.revisionId === item.revisionId) === index); return combined.sort((a, b) => a.createdAt.localeCompare(b.createdAt)); }
