export async function createCircularPattern(args: HistoryArgs & { input: CircularPatternInput }) { await authorize(args); const revisions = await listFeatureHistory(args); const source = revisions.find((item) => item.revisionId === args.input.sourceRevisionId); if (!source) throw new Error("The authorized source circle revision is unavailable; no pattern was attempted."); const values: PatternValues = { instanceCount: args.input.instanceCount, angleDegrees: args.input.angleDegrees, axis: args.input.axis, direction: args.input.direction }; const result = await buildCircularPattern({ ...args, input: args.input, values, source, decision: `Created guarded circular pattern from ${source.revisionId}.` }); if (result.status === "FAILED") { await persistFailure(args, result); return result; } histories.set(args.projectId, [...(histories.get(args.projectId) ?? []), result]); await persistRevision(args, result); await appendPersistentMemory({ ...args, record: { kind: "EVIDENCE", title: `Circular Pattern export provenance · ${result.revisionId}`, content: JSON.stringify(result.geometry.export?.provenance), truthStatus: "DERIVED", validationStage: "GEOMETRICALLY_VALIDATED", relatedConfigurationId: result.revisionId, authorSource: "CAD_AGENT" } }); return result; }
export async function previewCircularPatternRegeneration(args: HistoryArgs & { sourceRevisionId: string; edit: CircularPatternEdit }) { await authorize(args); const revisions = await listFeatureHistory(args); const source = revisions.find((item) => item.revisionId === args.sourceRevisionId); const pattern = source?.features.find((feature) => feature.featureType === "CIRCULAR_PATTERN"); if (!source || !pattern) throw new Error("A stored Circular Pattern revision is required for controlled pattern regeneration."); const values: PatternValues = { instanceCount: args.edit.instanceCount ?? Number(pattern.operationData?.instance_count), angleDegrees: args.edit.angleDegrees ?? Number(pattern.operationData?.angle_degrees), axis: args.edit.axis ?? (pattern.operationData?.axis as "GLOBAL_Z"), direction: args.edit.direction ?? (pattern.operationData?.direction as PatternValues["direction"]) }; const sourceCircle = revisions.find((item) => item.revisionId === pattern.operationData?.source_revision); if (!sourceCircle) throw new Error("The pattern’s declared immutable source circle revision is unavailable; no regeneration was attempted."); const preview = await buildCircularPattern({ ...args, input: { title: `${source.title} · Pattern Preview`, sourceRevisionId: sourceCircle.revisionId, sourceFeatureId: "EXTRUDE-CIRCLE-001", ...values }, values, source: sourceCircle, historyParentRevisionId: source.revisionId, preview: true, decision: `Preview pattern regeneration from ${source.revisionId}.` }); previews.set(key(args.projectId, preview.revisionId), preview); return preview; }
export async function executeCircularPatternRegeneration(args: HistoryArgs & { previewRevisionId: string }) { await authorize(args); const preview = previews.get(key(args.projectId, args.previewRevisionId)); if (!preview || preview.status !== "PREVIEW" || preview.geometry.validation !== "VALID") { const failed = preview ? { ...preview, status: "FAILED" as const, truth: "FACT" as const, failure: preview.failure ?? failure("VALIDATION", "Only a successful non-persistent pattern preview can execute.") } : undefined; if (failed) await persistFailure(args, failed); return failed ?? (() => { throw new Error("Pattern preview is unavailable or invalid; no source revision changed."); })(); } const pattern = preview.features.find((feature) => feature.featureType === "CIRCULAR_PATTERN")!; const revisions = await listFeatureHistory(args); const parentPattern = revisions.find((item) => item.revisionId === preview.parentRevisionId); const sourceCircle = revisions.find((item) => item.revisionId === pattern.operationData?.source_revision); if (!sourceCircle || !parentPattern) throw new Error("Pattern source or immutable parent revision is unavailable; no execution occurred."); const values: PatternValues = { instanceCount: Number(pattern.operationData?.instance_count), angleDegrees: Number(pattern.operationData?.angle_degrees), axis: pattern.operationData?.axis as "GLOBAL_Z", direction: pattern.operationData?.direction as PatternValues["direction"] }; const result = await buildCircularPattern({ ...args, input: { title: preview.title.replace(" · Pattern Preview", ""), sourceRevisionId: sourceCircle.revisionId, sourceFeatureId: "EXTRUDE-CIRCLE-001", ...values }, values, source: sourceCircle, historyParentRevisionId: parentPattern.revisionId, decision: `Approved guarded pattern preview ${preview.revisionId}.` }); if (result.status === "FAILED") { await persistFailure(args, result); return result; } histories.set(args.projectId, [...(histories.get(args.projectId) ?? []), result]); await persistRevision(args, result); return result; }
